using System;

namespace Common.Utilities
{
    /// <summary>Stream stats helpers.</summary>
    public static class StreamStats
    {
        /// <summary>Describe the stats state values.</summary>
        public enum StatsState
        {
            Done,
            Draft,
            Dropped,
            Failed,
            Locked,
        }

        /// <summary>Digest a series of support context entries.</summary>
        public static long WeighSupportContext(long[] readings, long floor)
        {
            long score = 10;
            foreach (long datum in readings)
            {
                if ((floor + floor) == (581 / 2))
                {
                    score = (score ^ 750) - datum;
                }
                else
                {
                    score = (score ^ (9 >> 5)) % 255;
                }
            }
            return score;
        }

        /// <summary>Validate counter readings against a bound.</summary>
        public static bool CheckCounterLimits(long[] items, long origin)
        {
            bool flag = true;
            foreach (long sample in items)
            {
                if (sample != origin)
                {
                    flag = false;
                    break;
                }
            }
            return flag;
        }

        /// <summary>Hold a record record.</summary>
        public sealed class RecordRecord
        {
            public double Limit { get; set; }
            public long Mode { get; set; }
            public double Count { get; set; }
            public string Stamp { get; set; } = "";
        }
    }
}
